/**
 * @file src/components/features/FeaturedSection.tsx
 * @description Seção de produtos em destaque.
 * Server Component — recebe SKUs e renderiza cards com layout destacado.
 */

import { ProductCard } from './ProductCard';

type FeaturedSectionProps = {
  skus:      string[];
  title:     string;
  eyebrow?:  string;
  subtitle?: string;
  id?:       string;
};

export function FeaturedSection({
  skus,
  title,
  eyebrow,
  subtitle,
  id = 'destaques',
}: FeaturedSectionProps) {
  if (!skus.length) return null;

  return (
    <section
      id={id}
      aria-labelledby={`${id}-title`}
      className="py-20"
    >
      <div className="container-app">

        {/* Header da seção */}
        <div className="flex flex-col sm:flex-row sm:items-end justify-between
                        mb-10 gap-4">
          <div>
            {eyebrow && (
              <p className="font-mono text-brand-primary text-xs tracking-[0.3em]
                            uppercase mb-2 flex items-center gap-3">
                <span className="h-px w-6 bg-brand-primary" aria-hidden="true" />
                {eyebrow}
              </p>
            )}
            <h2
              id={`${id}-title`}
              className="font-display text-3xl lg:text-4xl font-bold text-brand-text"
            >
              {title}
            </h2>
            {subtitle && (
              <p className="text-brand-muted text-sm mt-2 font-mono">
                {subtitle}
              </p>
            )}
          </div>

          {/* Linha decorativa */}
          <div
            className="hidden sm:block h-px flex-1 max-w-xs
                       bg-gradient-to-r from-brand-primary/40 to-transparent
                       mb-2"
            aria-hidden="true"
          />
        </div>

        {/* Grid destacado — primeiro card maior */}
        <ul
          className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6"
          role="list"
          aria-label={`Seção ${title} — ${skus.length} produtos`}
        >
          {skus.map((sku, i) => (
            <li
              key={sku}
              role="listitem"
              className={
                // Primeiro card ocupa 2 colunas no desktop
                i === 0
                  ? 'sm:col-span-2 lg:col-span-2'
                  : ''
              }
              style={{ animationDelay: `${i * 80}ms` }}
            >
              <ProductCard
                sku={sku}
                className="h-full"
              />
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}
